import Vue from 'vue';
import Vuex from 'vuex';

Vue.use(Vuex);

export const store = new Vuex.Store({
	state: {
		${1:key}: ${2:value}
	}
});

export default {
	state: {
		value: 'my value'
	},
	getters: {
		value: state => {
			return state.value;
		}
	},
	mutations: {
		updateValue(state, payload) {
			state.value = payload;
		}
	},
	actions: {
		updateValue({commit}, payload) {
			commit('updateValue', payload);
		}
	}
};

export const state = () => ({
	value: 'myvalue'
})

export const getters = {
	getterValue: state => {
		return state.value
	}
}

export const mutations = {
	updateValue: (state, payload) => {
		state.value = payload
	}
}

export const actions = {
